import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.DUVMSgRF.js";const g=JSON.parse('{"title":"算法体系文章系列 · 阅读指南","description":"","frontmatter":{"pageClass":"book book-algorithm"},"headers":[],"relativePath":"algorithm/index.md","filePath":"algorithm/index.md","lastUpdated":1793188998000}'),s={name:"algorithm/index.md"};function n(o,t,p,h,l,i){return a(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="算法体系文章系列-·-阅读指南" tabindex="-1">算法体系文章系列 · 阅读指南 <a class="header-anchor" href="#算法体系文章系列-·-阅读指南" aria-label="Permalink to &quot;算法体系文章系列 · 阅读指南&quot;">​</a></h1><p>这一系列是 1761 道刷题记录的<strong>细节手册</strong>。每篇文章对应一个算法主题，把「这类题长什么样、为什么能这么想、边界在哪、Go 怎么写」讲透。</p><p>配套的速查地图是<a href="https://billzong.github.io/post/8626f261.html" target="_blank" rel="noreferrer">算法体系总结-20261025.md</a>（21 个主题的全景脑图 + 套路清单 + 选型速查表）。<strong>用法是：先用汇总稿定位主题，再进对应文章看细节。</strong></p><h2 id="_1-先看哪几篇" tabindex="-1">1. 先看哪几篇 <a class="header-anchor" href="#_1-先看哪几篇" aria-label="Permalink to &quot;1. 先看哪几篇&quot;">​</a></h2><p>如果你是第一次系统过一遍，按这个顺序读，依赖关系最顺：</p><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>为什么放这个位置</th></tr></thead><tbody><tr><td>1</td><td><a href="./01-数组与字符串">01 数组与字符串</a></td><td>所有题目的载体，后面每一篇都建立在它上面</td></tr><tr><td>2</td><td><a href="./02-哈希表与计数">02 哈希表与计数</a></td><td>最常用的加速手段，<code>map</code> 的语义要一次讲清</td></tr><tr><td>3</td><td><a href="./05-栈与队列">05 栈与队列</a></td><td>单调栈 / 单调队列是后面多个主题的公共零件</td></tr><tr><td>4</td><td><a href="./08-二分查找">08 二分查找</a></td><td>「答案单调」这个思维方式比代码本身重要</td></tr><tr><td>5</td><td><a href="./09-滑动窗口与双指针">09 滑动窗口与双指针</a></td><td>把 O(n²) 压成 O(n) 的两种典型形态</td></tr><tr><td>6</td><td><a href="./12-深度优先搜索">12 深度优先搜索</a></td><td>回溯、连通块、拓扑都从这里长出来</td></tr><tr><td>7</td><td><a href="./13-广度优先搜索">13 广度优先搜索</a></td><td>与 DFS 构成图论的两只基本手</td></tr><tr><td>8</td><td><a href="./18-动态规划">18 动态规划</a></td><td>最需要状态设计的一类，单独留足篇幅</td></tr></tbody></table><p>其余 13 篇按需翻：遇到什么题就回到对应主题，不必按顺序读。</p><h2 id="_2-21-篇一览" tabindex="-1">2. 21 篇一览 <a class="header-anchor" href="#_2-21-篇一览" aria-label="Permalink to &quot;2. 21 篇一览&quot;">​</a></h2><p>「什么时候翻」这一列是<strong>题面信号</strong>，看到就跳过去。</p><table tabindex="0"><thead><tr><th>#</th><th>文章</th><th>什么时候翻</th></tr></thead><tbody><tr><td>01</td><td><a href="./01-数组与字符串">数组与字符串</a></td><td>输入是一维序列；要统计、比较、变换某个连续段；要求原地改</td></tr><tr><td>02</td><td><a href="./02-哈希表与计数">哈希表与计数</a></td><td>要判重复、统计频次、记录「上次出现位置」；要 O(1) 判存在</td></tr><tr><td>03</td><td><a href="./03-排序">排序</a></td><td>要第 K 大/小；要按位次处理；要「排序后相邻配对」；要自定义比较规则</td></tr><tr><td>04</td><td><a href="./04-链表">链表</a></td><td>题面给 head / 节点结构；要反转、断链、合并；出现「倒数第 k 个」「找环」「找交点」</td></tr><tr><td>05</td><td><a href="./05-栈与队列">栈与队列</a></td><td>括号匹配、表达式求值、单调性维护、层序遍历、固定窗口最值</td></tr><tr><td>06</td><td><a href="./06-字典树">字典树</a></td><td>大量字符串且查询以字符串前缀出现；统计以某串开头的数量；自动补全</td></tr><tr><td>07</td><td><a href="./07-堆">堆</a></td><td>Top K、第 K 大/小、流式最值、多路归并、任务调度</td></tr><tr><td>08</td><td><a href="./08-二分查找">二分查找</a></td><td>答案空间是整数区间；要求最小/最大值满足某条件；有序数组找边界</td></tr><tr><td>09</td><td><a href="./09-滑动窗口与双指针">滑动窗口与双指针</a></td><td>连续子数组/子串的最长最短；要「窗口内不重复/不超限」；两数之和的变体</td></tr><tr><td>10</td><td><a href="./10-前缀和">前缀和</a></td><td>问连续区间的和或和的某个性质；「和为 K 的子数组」；二维矩形区域和</td></tr><tr><td>11</td><td><a href="./11-递归与分治">递归与分治</a></td><td>题面有「在区间里选」「合并两个有序序列」「求中位数」；要把 O(n²) 降到 O(n log n)</td></tr><tr><td>12</td><td><a href="./12-深度优先搜索">深度优先搜索</a></td><td>连通块计数；枚举所有可能方案；路径搜索；依赖关系判环</td></tr><tr><td>13</td><td><a href="./13-广度优先搜索">广度优先搜索</a></td><td>求最短步数/最短距离；按层输出；状态空间是一张隐式图</td></tr><tr><td>14</td><td><a href="./14-树">树</a></td><td>题面给二叉树 / BST；求路径和、深度、直径、LCA；要序列化</td></tr><tr><td>15</td><td><a href="./15-图">图</a></td><td>题面给边集或邻接表；求路径/顺序/连通分量；判断有无环</td></tr><tr><td>16</td><td><a href="./16-贪心">贪心</a></td><td>求最大值/最小值且答案能逐步构造；区间选择类；排序后按序处理</td></tr><tr><td>17</td><td><a href="./17-位运算与数学">位运算与数学</a></td><td>出现「只出现一次」「子集」「异或」「每个元素出现 k 次」；涉及整除、余数、进制、约数、质数</td></tr><tr><td>18</td><td><a href="./18-动态规划">动态规划</a></td><td>求最优解或计数；存在重叠子问题；有「无后效性」</td></tr><tr><td>19</td><td><a href="./19-设计类">设计类</a></td><td>要你实现一个类，含 add/remove/query 等多个操作，且有性能要求</td></tr><tr><td>20</td><td><a href="./20-模拟">模拟</a></td><td>描述一堆操作问某个时刻的状态；「实现一个……类/方法」但没有性能要求</td></tr><tr><td>21</td><td><a href="./21-数据库与SQL">数据库与 SQL</a></td><td>给表结构和查询要求，返回一张表</td></tr></tbody></table><h2 id="_3-每篇文章的结构" tabindex="-1">3. 每篇文章的结构 <a class="header-anchor" href="#_3-每篇文章的结构" aria-label="Permalink to &quot;3. 每篇文章的结构&quot;">​</a></h2><p>七节固定，方便你按需跳读：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 场景        这类题长什么样，约束里藏着什么决定性条件</span></span>
<span class="line"><span>2. 核心机制    为什么这类题能被这个方法解（推导，不是结论）</span></span>
<span class="line"><span>3. 套路清单    可直接抄的招式表：做法 / 复杂度 / 前提与坑</span></span>
<span class="line"><span>4. Go 实现     逐题：题目要点 → 教学实现 → 讲解 → 真实运行结果</span></span>
<span class="line"><span>5. 变体与边界  同一手法的其他题型，差在哪一处</span></span>
<span class="line"><span>6. 常见错误    实战真会踩的坑</span></span>
<span class="line"><span>7. 延伸        相关题号 + 仓库路径 + 汇总稿对应小节</span></span></code></pre></div><p>想快速过一遍就只看 <strong>3 套路清单</strong> 和 <strong>6 常见错误</strong>；想真正吃透就看 <strong>2 核心机制</strong> 和 <strong>4 Go 实现</strong>。</p><blockquote><p>输出块的两种排版：<strong>4.1–4.x 每小节各自带一个 <code>text</code> 块</strong>（多数篇目如此）；<strong>05 栈与队列</strong>、<strong>06 字典树</strong>两篇为了控制篇幅，把每小节的结果压成一行内联摘要，完整 stdout 统一放在该篇末尾的「完整可运行示例」里。信息量相同，只是摆放位置不同。</p></blockquote><h2 id="_4-本系列的三条约定" tabindex="-1">4. 本系列的三条约定 <a class="header-anchor" href="#_4-本系列的三条约定" aria-label="Permalink to &quot;4. 本系列的三条约定&quot;">​</a></h2><p><strong>一、Go 示例是重写的精简教学版，不是仓库代码的复制。</strong> 仓库 <code>leetcode-answers</code> 里每道题都有工程化的完整实现（含基准测试、性能基线、复杂度分析）。文章里的代码是<strong>另写的一份精简版</strong>：只保留教学点，注释只解释「为什么」。两者行为必须一致——每篇文章的示例都在临时模块里跟仓库真实实现做过<strong>差分对拍</strong>（固定边界用例 + 固定种子的随机用例），差异必须为空。需要看完整工程化写法时，文章里给了仓库路径。</p><p><strong>二、「运行结果」是实测输出。</strong> 每篇文章末尾的 <code>text</code> 代码块是程序真实跑出来的 stdout，逐字复制，不是手写的示意。示例至少覆盖 3 组输入：题面示例 + 2 组边界或变体（空输入 / 单元素 / 重复 / 全同 / 极值），输出能直接看出边界是怎么处理的。</p><p><strong>三、题号、题名、难度与仓库逐字对齐。</strong> 文中出现的每个题号都在 <code>leetcode-answers</code> 仓库里有真实目录，题名与难度取自该题的 README。仓库里某题没收录更优解时，延伸清单会明说「未收录」，不硬凑。</p><h2 id="_5-与汇总稿的关系" tabindex="-1">5. 与汇总稿的关系 <a class="header-anchor" href="#_5-与汇总稿的关系" aria-label="Permalink to &quot;5. 与汇总稿的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><a href="https://billzong.github.io/post/8626f261.html" target="_blank" rel="noreferrer">算法体系总结-20261025.md</a>（汇总稿）</th><th>本系列</th></tr></thead><tbody><tr><td>定位</td><td>速查地图</td><td>细节手册</td></tr><tr><td>形态</td><td>每主题 5 段 + 4 张全景脑图</td><td>每主题 7 段 + 逐题 Go 教学实现</td></tr><tr><td>什么时候用</td><td>拿到新题，先定位主题</td><td>定位到主题后，看清机制与边界</td></tr><tr><td>篇幅</td><td>约 930 行</td><td>每篇 200–400 行，共 21 篇</td></tr></tbody></table><p>两边的结论一致。个别地方文章里的写法更简洁（例如教学版代码可能用更短的写法），<strong>细节以文章为准</strong>，汇总稿负责导航。</p><h2 id="_6-仓库对照" tabindex="-1">6. 仓库对照 <a class="header-anchor" href="#_6-仓库对照" aria-label="Permalink to &quot;6. 仓库对照&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>leetcode-answers/</span></span>
<span class="line"><span>├── &lt;题号&gt;-&lt;slug&gt;/</span></span>
<span class="line"><span>│   ├── README.md              # 官方题面原文（示例与约束）</span></span>
<span class="line"><span>│   ├── NOTE.md                # 实际采用的解法 + 性能基线 + 卡点</span></span>
<span class="line"><span>│   ├── solution.go            # 工程化实现（部分题是 solution.sql）</span></span>
<span class="line"><span>│   ├── solution_test.go       # 单测（期望值由暴力解或独立实现推导）</span></span>
<span class="line"><span>│   └── other-best-answers/    # 收录的公开更优解</span></span></code></pre></div><p>文章里提到某个题号时，对应目录就是上面这个结构；<code>4. Go 实现</code> 小节末尾的「仓库实现」一行给的就是相对路径。</p>`,25)])])}const b=d(s,[["render",n]]);export{g as __pageData,b as default};
